) VALUES (
  'IND-360',                                   -- id
  'cowin-vaccination-platform',                -- slug
  'computing',                                 -- discipline_id
  'CoWIN vaccination platform',                -- title
  'Government of India',                       -- originator
  '2021',                                      -- period
  2021,                                        -- year_start
  2021,                                        -- year_end
  'CoWIN',                                     -- source_text
  'A national digital platform that scheduled and certified over two billion COVID-19 vaccine doses.', -- description
  'India began vaccinating against COVID-19 in January 2021 and needed one system to book appointments, record every dose and issue proof of vaccination for well over a billion people. CoWIN, run by the health ministry, did all three, with certificates generated by DIVOC, an open-source credentialing stack built by the eGov Foundation.', -- background
  'It showed that a national vaccination drive could run on a single digital registry at continental scale, issuing signed, QR-verifiable certificates for every dose. Its reliance on online booking also became a test case for the digital divide, and the Supreme Court pressed the government to open walk-in and offline routes.', -- significance
  NULL,                                        -- western_parallel
  'Offered as open-source to other countries.', -- transmission_note
  'Part of India''s digital public infrastructure.', -- modern_relevance
  NULL,                                        -- modern_value
  'Documented',                                -- evidence_tier
  'Medium',                                    -- confidence
  'A 2023 data-leak allegation raised privacy concerns.', -- caveat
  'Pan-Indian / unspecified',                  -- region
  'Reference-cited',                           -- verification
  'CoWIN',                                     -- wikipedia
  NULL,                                        -- image_url
  NULL                                         -- image_credit
);

